import { ProfilePatch } from './types';

const MIN_DISPLAY_NAME_LENGTH = 1;
const MAX_DISPLAY_NAME_LENGTH = 40;
const MAX_TAG_COUNT = 5;
const MIN_TAG_LENGTH = 1;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

function isPlainObject(input: object): boolean {
  const prototype: unknown = Object.getPrototypeOf(input);
  return prototype === null || prototype === Object.prototype;
}

function ownKeys(input: object): Array<string | symbol> {
  return [...Object.getOwnPropertyNames(input), ...Object.getOwnPropertySymbols(input)];
}

function readField(input: object, key: string): unknown {
  return (input as Record<string, unknown>)[key];
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') return invalid();
  const trimmed = value.trim();
  if (trimmed.length < MIN_DISPLAY_NAME_LENGTH || trimmed.length > MAX_DISPLAY_NAME_LENGTH) return invalid();
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) return invalid();
  if (value.length > MAX_TAG_COUNT) return invalid();
  const tags: string[] = [];
  for (const element of value) {
    if (typeof element !== 'string') return invalid();
    const trimmed = element.trim();
    if (trimmed.length < MIN_TAG_LENGTH || trimmed.length > MAX_TAG_LENGTH) return invalid();
    if (tags.includes(trimmed)) return invalid();
    tags.push(trimmed);
  }
  return tags;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input) || !isPlainObject(input)) {
    return invalid();
  }
  const keys = ownKeys(input);
  for (const key of keys) {
    if (key !== 'displayName' && key !== 'tags') return invalid();
  }
  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  for (const key of keys) {
    if (key === 'displayName') displayName = { kind: 'set', value: parseDisplayName(readField(input, key)) };
    else if (key === 'tags') tags = { kind: 'set', value: parseTags(readField(input, key)) };
  }
  return { displayName, tags };
}
